                                }
                            }
                            Err(e) => {
                                warn!("Failed to parse WS command: {}", e);
                                let _ = event_tx.send(WsEvent::System(SystemWsEvent::Error {
                                    error: format!("Invalid command: {}", e),
                                }));
                            }
