                        // Pong is handled automatically by axum's WebSocket
                        let _ = data;
                    }
                    Some(Ok(Message::Close(_))) => break,
                    Some(Err(e)) => {
                        warn!("WebSocket error: {}", e);
                        break;
                    }
                    None => break,
                    _ => {}
                }
            }
        }
    }

    // Cleanup
    event_writer.abort();
    info!("Multiplexed WebSocket closed for user {}", user_id);
