/// Handle a WebSocket command and return an optional response event.
async fn handle_ws_command(
    cmd: WsCommand,
    user_id: &str,
    state: &AppState,
    runner_client: Option<&RunnerClient>,
    conn_state: Arc<tokio::sync::Mutex<WsConnectionState>>,
) -> Option<WsEvent> {
    match cmd {
        WsCommand::Pi(pi_cmd) => {
            handle_pi_command(pi_cmd, user_id, state, runner_client, conn_state).await
        }
        WsCommand::Files(files_cmd) => handle_files_command(files_cmd).await,
        WsCommand::Terminal(term_cmd) => handle_terminal_command(term_cmd).await,
        WsCommand::Hstry(hstry_cmd) => handle_hstry_command(hstry_cmd).await,
    }
}

