		let handlers = this.channelHandlers.get(channel);
		if (!handlers) {
			handlers = new Set();
			this.channelHandlers.set(channel, handlers);
		}
		handlers.add(handler);

		return () => {
			handlers?.delete(handler);
			if (handlers?.size === 0) {
				this.channelHandlers.delete(channel);
			}
		};
	}

