		if (!handlers) {
			handlers = new Set();
			this.piSessionHandlers.set(sessionId, handlers);
		}
		handlers.add(handler);

		// Track subscription (store config for reconnection)
		if (!this.subscribedSessions.has(sessionId)) {
			this.subscribedSessions.set(sessionId, config);

			if (this.isConnected) {
