        }
        PiEvent::HookError { error, .. } => WsEvent::Pi(PiWsEvent::Error {
            id: None,
            session_id: sid,
            error,
        }),
        PiEvent::Unknown => {
            debug!("Received unknown Pi event type");
            WsEvent::Pi(PiWsEvent::State {
                id: None,
                session_id: sid,
                state: Value::Null,
            })
        }
    }
}

