function TreeRow({
	node,
	level,
	expanded,
	onToggle,
	onSelectFile,
	selectedFiles,
	onNavigateToFolder,
	onDownload,
	onDelete,
	onRename,
	renamingPath,
	onRenameConfirm,
	onRenameCancel,
	onOpenInCanvas,
}: {
	node: FileNode;
	level: number;
	expanded: Record<string, boolean>;
	onToggle: (path: string) => void;
	onSelectFile: (
		path: string,
		name: string,
		isDirectory: boolean,
		event?: React.MouseEvent,
	) => void;
	selectedFiles: Set<string>;
	onNavigateToFolder: (path: string) => void;
	onDownload: (path: string, isDirectory: boolean) => void;
	onDelete: (path: string) => void;
	onRename: (path: string, currentName: string) => void;
	renamingPath: string | null;
	onRenameConfirm: (newName: string) => void;
	onRenameCancel: () => void;
	onOpenInCanvas?: (path: string) => void;
}) {
	const isDir = node.type === "directory";
	const isExpanded = expanded[node.path];
	const isSelected = selectedFiles.has(node.path);
	const isRenaming = renamingPath === node.path;

	// Sort children: directories first, then files
	const sortedChildren = node.children
		? [...node.children].sort((a, b) => {
				if (a.type === "directory" && b.type !== "directory") return -1;
				if (a.type !== "directory" && b.type === "directory") return 1;
				return a.name.localeCompare(b.name);
			})
		: [];

	const handleClick = (e: React.MouseEvent) => {
		e.stopPropagation();
		if (e.shiftKey) {
			// Shift+click: select/multi-select
			onSelectFile(node.path, node.name, isDir, e);
		} else if (isDir) {
			// Click on folder: expand/collapse
			onToggle(node.path);
		} else {
			// Click on file: preview
			onSelectFile(node.path, node.name, isDir, e);
		}
	};

	const handleDoubleClick = () => {
		if (isDir) {
			onNavigateToFolder(node.path);
		}
	};

	return (
		<li>
			<FileContextMenu
				node={node}
				onDownload={onDownload}
				onDelete={onDelete}
				onRename={onRename}
				onOpenInCanvas={onOpenInCanvas}
			>
				<button
					type="button"
					className={cn(
						"flex items-center gap-1.5 py-1.5 px-2 cursor-pointer transition-colors w-full",
						isSelected
							? "bg-primary/10 text-primary"
							: "hover:bg-muted text-muted-foreground hover:text-foreground",
					)}
					style={{ paddingLeft: `${level * 16 + 8}px` }}
					onClick={isRenaming ? undefined : handleClick}
					onDoubleClick={isRenaming ? undefined : handleDoubleClick}
				>
					{isDir ? (
						<span className="flex-shrink-0 text-muted-foreground">
							{isExpanded ? (
								<ChevronDown className="w-4 h-4" />
							) : (
								<ChevronRight className="w-4 h-4" />
							)}
						</span>
					) : (
						<span className="w-4 flex-shrink-0" />
					)}
					<FileIcon
						filename={node.name}
						isDirectory={isDir}
						size={18}
						className="flex-shrink-0"
					/>
					{isRenaming ? (
						<RenameInput
							initialValue={node.name}
							onConfirm={onRenameConfirm}
							onCancel={onRenameCancel}
						/>
					) : (
						<span className="truncate text-sm">{node.name}</span>
					)}
					{!isRenaming && isDir && node.children && (
						<span className="text-xs text-muted-foreground/60 ml-auto pr-2">
							{node.children.length}
						</span>
					)}
				</button>
			</FileContextMenu>
			{isDir && isExpanded && sortedChildren.length > 0 && (
				<ul>
					{sortedChildren.map((child) => (
						<TreeRow
							key={child.path}
							node={child}
							level={level + 1}
							expanded={expanded}
							onToggle={onToggle}
							onSelectFile={onSelectFile}
							selectedFiles={selectedFiles}
							onNavigateToFolder={onNavigateToFolder}
							onDownload={onDownload}
							onDelete={onDelete}
							onRename={onRename}
							renamingPath={renamingPath}
							onRenameConfirm={onRenameConfirm}
							onRenameCancel={onRenameCancel}
							onOpenInCanvas={onOpenInCanvas}
						/>
					))}
				</ul>
			)}
		</li>
	);
}

