// Flatten file tree for searching
function flattenTree(nodes: FileNode[], result: FileNode[] = []): FileNode[] {
	for (const node of nodes) {
		if (node.type === "file") {
			result.push(node);
		}
	}
	return result;
}

// Simple fuzzy match
function fuzzyMatch(query: string, text: string): boolean {
	if (!query) return true;
	const lowerQuery = query.toLowerCase();
	const lowerText = text.toLowerCase();

	// Check if all characters appear in order
	let qi = 0;
	for (let i = 0; i < lowerText.length && qi < lowerQuery.length; i++) {
		if (lowerText[i] === lowerQuery[qi]) {
			qi++;
		}
	}
	return qi === lowerQuery.length;
}

// Score a match (higher = better)
function matchScore(query: string, text: string): number {
	if (!query) return 0;
	const lowerQuery = query.toLowerCase();
	const lowerText = text.toLowerCase();

	// Exact match at start
	if (lowerText.startsWith(lowerQuery)) return 100;
	// Contains
	if (lowerText.includes(lowerQuery)) return 50;
	// Fuzzy
	return 10;
}

async function fetchAllFiles(
	baseUrl: string,
